import {normalizeDocument,validDocument,companyRecord,mapRegisterRows} from '../core/registers.js?v=20261111-v15a';
import {readCSV} from '../core/statements.js?v=20261111-v15a';
export function install(ctx){
 const contacts=()=>[...(ctx.clients||[]).map(x=>({...x,register_type:'clients'})),...(ctx.suppliers||[]).map(x=>({...x,register_type:'suppliers'}))];
 const existingDocument=(type,document,exclude)=>{const normalized=normalizeDocument(document);return validDocument(normalized)?(type==='suppliers'?ctx.suppliers||[]:ctx.clients||[]).find(x=>x.id!==exclude&&normalizeDocument(x.document)===normalized):null};
 async function documentRecord(document,type){const normalized=normalizeDocument(document);if(!validDocument(normalized))throw Error('Informe um CPF ou CNPJ válido para consultar.');const found=contacts().filter(x=>normalizeDocument(x.document)===normalized).sort((a,b)=>Number(b.register_type===type)-Number(a.register_type===type))[0];if(found)return {...found,...(found.register_type===type?{}:{id:undefined,register_type:type}),lookup_source:found.register_type===type?'Cadastro privado da Avelon':'Dados encontrados em outro cadastro da Avelon. Confira e salve como '+(type==='suppliers'?'fornecedor.':'cliente.')};
  if(normalized.length===11)return {kind:'PF',document:normalized,name:'',lookup_source:'CPF não encontrado na base da Avelon. Complete o cadastro com os dados informados pelo cliente ou fornecedor.'};
  const response=await fetch('https://brasilapi.com.br/api/cnpj/v1/'+encodeURIComponent(normalized),{signal:AbortSignal.timeout(12000),credentials:'omit'});if(!response.ok)throw Error(response.status===404?'CNPJ não encontrado na base pública. Preencha os dados manualmente.':'A consulta pública está indisponível. Você pode preencher o cadastro manualmente.');const data=companyRecord(await response.json());if(!data.name)throw Error('A consulta não retornou o nome empresarial.');return {...data,lookup_source:'BrasilAPI · dados públicos de CNPJ. Confira as informações antes de salvar.'};
 }
 function fillContact(form,record){for(const name of ['kind','name','document','phone','email','address']){const input=form.elements.namedItem(name);if(input&&record[name]!=null&&record[name]!=='')input.value=record[name]}}
 function addDocumentLookup(form,{type='clients'}={}){const documentInput=form.elements.namedItem('document');if(!documentInput||form.querySelector('[data-document-lookup]'))return;const controls=document.createElement('div');controls.className='span2';controls.dataset.documentLookup='';controls.innerHTML='<button type="button" class="secondary small">Buscar CPF / CNPJ</button><p class="muted helper" role="status">CPF: busca nos cadastros privados da Avelon. CNPJ: base própria e consulta pública gratuita pela BrasilAPI.</p><a href="https://solucoes.receita.fazenda.gov.br/Servicos/cpf/ConsultaSituacao/ConsultaPublica.asp" target="_blank" rel="noopener noreferrer" class="helper">Consultar situação do CPF no site oficial da Receita</a>';documentInput.closest('label').after(controls);const button=controls.querySelector('button'),status=controls.querySelector('[role="status"]');button.onclick=async()=>{button.disabled=true;try{const record=await documentRecord(documentInput.value,type);fillContact(form,record);status.textContent=record.lookup_source}catch(error){status.textContent=error.message}finally{button.disabled=false}}}
 function contactFields(record={}){return `<label class="field">Tipo<select name="kind"><option value="PF" ${record.kind==='PF'?'selected':''}>Pessoa física</option><option value="PJ" ${record.kind!=='PF'?'selected':''}>Pessoa jurídica</option></select></label>${ctx.field('Nome / razão social','name','text',record.name||'','required minlength="2" maxlength="200"')}${ctx.field('CPF / CNPJ','document','text',record.document||'','maxlength="20"')}${ctx.field('Telefone / WhatsApp','phone','tel',record.phone||'','maxlength="25"')}${ctx.field('E-mail','email','email',record.email||'','maxlength="200"')}${ctx.field('Endereço','address','text',record.address||'','maxlength="500"')}`}
 function supplierDialog(record=null,onSaved){if(!ctx.can('suppliers',record?'edit':'create'))return ctx.toast('Seu acesso não permite esse cadastro.');const d=ctx.modal(record?'Editar fornecedor':'Cadastrar fornecedor',`<form><div class="grid2">${contactFields(record||{})}</div><p role="alert" class="form-error"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary" type="submit">Salvar fornecedor</button></div></form>`,{wide:true});const form=d.querySelector('form');addDocumentLookup(form,{type:'suppliers'});form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const values=Object.fromEntries(new FormData(form));const duplicate=existingDocument('suppliers',values.document,record?.id);if(duplicate)throw Error('Este CPF/CNPJ já está cadastrado como fornecedor: '+duplicate.name);const result=await ctx.api('/rest/v1/suppliers'+(record?'?id=eq.'+record.id:''),{method:record?'PATCH':'POST',body:values,headers:{Prefer:'return=representation'}});await ctx.load();d.close();if(ctx.current==='suppliers')suppliersPage();await onSaved?.(result[0]);ctx.toast('Fornecedor salvo.')}catch(error){d.querySelector('[role="alert"]').textContent=error.message;button.disabled=false}};return {dialog:d,form}}
 function suppliersPage(){ctx.shell(`${ctx.head('Fornecedores','Contatos e documentos organizados na base privada da Avelon.')}<div class="toolbar">${ctx.can('suppliers','create')?'<button class="primary" id="new-supplier">Cadastrar fornecedor</button>':''}${ctx.profile.is_owner?'<button class="secondary" id="import-registers">Importar planilha</button>':''}<input type="search" id="supplier-search" aria-label="Buscar fornecedor" placeholder="Buscar nome ou CPF/CNPJ…"></div><section class="panel" id="supplier-list"></section>`);function draw(){const search=ctx.$('#supplier-search').value.toLocaleLowerCase(),rows=(ctx.suppliers||[]).filter(x=>(x.name+' '+x.document).toLocaleLowerCase().includes(search));ctx.$('#supplier-list').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Fornecedor</th><th>CPF / CNPJ</th><th>Contato</th><th>Situação</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${ctx.esc(x.name)}</strong></td><td>${ctx.esc(x.document)||'—'}</td><td>${ctx.esc(x.phone)}<br>${ctx.esc(x.email)}</td><td>${x.active?'Ativo':'Inativo'}</td><td>${ctx.can('suppliers','edit')?`<button class="secondary small" data-edit-supplier="${x.id}">Editar</button> <button class="secondary small" data-active-supplier="${x.id}">${x.active?'Inativar':'Reativar'}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:ctx.empty('Nenhum fornecedor encontrado.','Cadastre um fornecedor ou importe uma planilha.');ctx.$('#supplier-list').querySelectorAll('[data-edit-supplier]').forEach(button=>button.onclick=()=>supplierDialog(rows.find(x=>x.id===button.dataset.editSupplier)));ctx.$('#supplier-list').querySelectorAll('[data-active-supplier]').forEach(button=>button.onclick=async()=>{const item=rows.find(x=>x.id===button.dataset.activeSupplier);try{await ctx.api('/rest/v1/suppliers?id=eq.'+item.id,{method:'PATCH',body:{active:!item.active}});await ctx.load();draw()}catch(error){ctx.toast(error.message)}})}draw();ctx.$('#supplier-search').oninput=draw;ctx.$('#new-supplier')?.addEventListener('click',()=>supplierDialog());ctx.$('#import-registers')?.addEventListener('click',()=>registerImportDialog('suppliers'))}
 function partyLookupDialog(type,onPick,context='cadastro'){const d=ctx.modal('Buscar cadastro por CPF / CNPJ',`<form>${ctx.field('CPF / CNPJ','document','text','','required maxlength="20"')}<p class="helper muted">Busca primeiro na base da Avelon. Para empresas não cadastradas, consulta dados públicos de CNPJ pela BrasilAPI.</p><p role="status"></p><div class="form-actions"><button class="primary" type="submit">Consultar</button><button class="secondary" type="button" data-close>Fechar</button></div></form><div id="party-result"></div>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const record=await documentRecord(new FormData(e.target).get('document'),type);d.querySelector('[role="status"]').textContent=record.lookup_source;d.querySelector('#party-result').innerHTML=`<p><strong>${ctx.esc(record.name||'Novo cadastro')}</strong><br>${ctx.esc(record.document)}</p>${record.id?'<button class="primary" id="use-party">Usar este cadastro</button>':ctx.can(type,'create')?'<button class="primary" id="create-party">Cadastrar '+(type==='suppliers'?'fornecedor':'cliente')+'</button>':'<p>Peça ao Mestre Criador para liberar o cadastro.</p>'}`;d.querySelector('#use-party')?.addEventListener('click',()=>{d.close();onPick(record)});d.querySelector('#create-party')?.addEventListener('click',()=>{d.close();if(type==='suppliers'){const editor=supplierDialog(null,onPick);if(editor)fillContact(editor.form,record)}else{ctx.quickRecordDialog('clients',onPick,record,context)}})}catch(error){d.querySelector('[role="status"]').textContent=error.message}finally{e.submitter.disabled=false}}}
 function registerImportDialog(initial='clients'){if(!ctx.profile?.is_owner)return ctx.toast('Importação exclusiva do Mestre Criador.');let rows=null,source=null;const d=ctx.modal('Importar cadastros da planilha',`<form><label class="field">Cadastro de destino<select name="type"><option value="clients" ${initial==='clients'?'selected':''}>Clientes</option><option value="suppliers" ${initial==='suppliers'?'selected':''}>Fornecedores</option><option value="products" ${initial==='products'?'selected':''}>Produtos</option></select></label><label class="field">Planilha CSV · até 5 MB<input type="file" name="file" accept=".csv,text/csv" required></label><label class="field">Separador<select name="separator"><option value=";">Ponto e vírgula</option><option value=",">Vírgula</option><option value="tab">Tabulação</option></select></label><p class="note">No Excel ou Google Sheets, exporte a aba como CSV. O sistema mantém sua base própria e registra a origem da importação. Cadastros duplicados são conferidos; preços atuais não são substituídos. Clientes existentes recebem apenas os dados que estiverem vazios.</p><p role="alert"></p><div id="register-preview"></div><div class="form-actions"><button class="secondary" type="button" data-close>Cancelar</button><button class="secondary" id="preview-registers" type="button">Conferir planilha</button><button class="primary" type="submit" disabled>Importar cadastros conferidos</button></div></form>`,{wide:true});const form=d.querySelector('form'),submit=form.querySelector('[type="submit"]'),error=form.querySelector('[role="alert"]');const reset=()=>{rows=null;source=null;submit.disabled=true;form.querySelector('#register-preview').innerHTML=''};form.addEventListener('change',reset);form.querySelector('#preview-registers').onclick=async()=>{error.textContent='';try{const file=form.elements.file.files[0];if(!file||file.size>5*1024*1024)throw Error('Escolha um CSV de até 5 MB.');rows=mapRegisterRows(readCSV(await file.text(),form.elements.separator.value),form.elements.type.value);if(!rows.length||rows.length>1000)throw Error('Importe entre 1 e 1.000 registros por arquivo.');source={name:file.name,uri:'csv:'+file.name,sheet:form.elements.type.value};form.querySelector('#register-preview').innerHTML=`<p>${rows.length} registros para conferência · ${rows.filter(x=>x.warning).length} avisos de CPF/CNPJ.</p><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Documento / referência</th><th>Aviso</th></tr></thead><tbody>${rows.slice(0,15).map(x=>`<tr><td>${ctx.esc(x.name)}</td><td>${ctx.esc(x.document||x.reference||'')}</td><td>${ctx.esc(x.warning||'')}</td></tr>`).join('')}</tbody></table></div>${rows.length>15?'<p class="muted">Prévia dos primeiros 15 registros.</p>':''}`;submit.disabled=false}catch(e){error.textContent=e.message;reset()}};form.onsubmit=async e=>{e.preventDefault();if(!rows||!source)return;submit.disabled=true;try{const result=await ctx.rpc('import_register_batch',{p_type:form.elements.type.value,p_source:source,p_rows:rows});await ctx.load();d.close();ctx.toast(`${result.inserted} novos · ${result.updated} complementados · ${result.skipped} já existentes.`);ctx.render(form.elements.type.value)}catch(err){error.textContent=err.message;submit.disabled=false}}}
 Object.assign(ctx,{existingDocument,documentRecord,addDocumentLookup,fillContact,suppliersPage,supplierDialog,partyLookupDialog,registerImportDialog});
}
